#[test]
fn x86_64_abi() {
    let mut c = Checker::new("x86_64", X86_64);
    common(&mut c);
    c.syscalls(x64::nr::TABLE);
    c.flags::<x64::OpenFlags>("O_", &[("ASYNC", "FASYNC")]);
    consts!(c;
        x64::O_DIRECT => "O_DIRECT", x64::O_LARGEFILE => "O_LARGEFILE",
        x64::O_DIRECTORY => "O_DIRECTORY", x64::O_NOFOLLOW => "O_NOFOLLOW",
        x64::O_TMPFILE => "O_TMPFILE",
        x64::MAP_32BIT => "MAP_32BIT", x64::MAP_ABOVE4G => "MAP_ABOVE4G",
        x64::MINSIGSTKSZ => "MINSIGSTKSZ", x64::SIGSTKSZ => "SIGSTKSZ",
        x64::ARCH_SET_GS => "ARCH_SET_GS", x64::ARCH_SET_FS => "ARCH_SET_FS",
        x64::ARCH_GET_FS => "ARCH_GET_FS", x64::ARCH_GET_GS => "ARCH_GET_GS",
        x64::ARCH_GET_CPUID => "ARCH_GET_CPUID", x64::ARCH_SET_CPUID => "ARCH_SET_CPUID",
        x64::UC_FP_XSTATE => "UC_FP_XSTATE", x64::UC_SIGCONTEXT_SS => "UC_SIGCONTEXT_SS",
        x64::UC_STRICT_RESTORE_SS => "UC_STRICT_RESTORE_SS",
        x64::FP_XSTATE_MAGIC1 => "FP_XSTATE_MAGIC1", x64::FP_XSTATE_MAGIC2 => "FP_XSTATE_MAGIC2",
        x64::FP_XSTATE_MAGIC2_SIZE => "FP_XSTATE_MAGIC2_SIZE",
        x64::REDZONE => "REDZONE", x64::FPSTATE_ALIGN => "FPSTATE_ALIGN",
        x64::FRAME_ALIGNMENT => "FRAME_ALIGNMENT",
    );
    c.eq("_header.__size", x64::XSAVE_HEADER_SIZE);
    c.ignore("_header.__align", "only the size is used");
    layout!(c, x64::Stat, "stat" {
        st_dev => "st_dev", st_ino => "st_ino", st_nlink => "st_nlink", st_mode => "st_mode",
        st_uid => "st_uid", st_gid => "st_gid", _pad0 => "__pad0", st_rdev => "st_rdev",
        st_size => "st_size", st_blksize => "st_blksize", st_blocks => "st_blocks",
        st_atime => "st_atime", st_atime_nsec => "st_atime_nsec", st_mtime => "st_mtime",
        st_mtime_nsec => "st_mtime_nsec", st_ctime => "st_ctime",
        st_ctime_nsec => "st_ctime_nsec", _unused => "__unused" });
    layout!(c, x64::EpollEvent, "epoll_event" { events => "events", data => "data" });
    layout!(c, x64::SigContext, "sigcontext" {
        r8 => "r8", r9 => "r9", r10 => "r10", r11 => "r11", r12 => "r12", r13 => "r13",
        r14 => "r14", r15 => "r15", rdi => "rdi", rsi => "rsi", rbp => "rbp", rbx => "rbx",
        rdx => "rdx", rax => "rax", rcx => "rcx", rsp => "rsp", rip => "rip",
        eflags => "eflags", cs => "cs", gs => "gs", fs => "fs", ss => "ss", err => "err",
        trapno => "trapno", oldmask => "oldmask", cr2 => "cr2", fpstate => "fpstate",
        reserved1 => "reserved1" });
    layout!(c, x64::FpxSwBytes, "_fpx_sw_bytes" {
        magic1 => "magic1", extended_size => "extended_size", xfeatures => "xfeatures",
        xstate_size => "xstate_size", padding => "padding" });
    layout!(c, x64::FpState, "_fpstate_64" {
        cwd => "cwd", swd => "swd", twd => "twd", fop => "fop", rip => "rip", rdp => "rdp",
        mxcsr => "mxcsr", mxcsr_mask => "mxcsr_mask", st_space => "st_space",
        xmm_space => "xmm_space", reserved2 => "reserved2", sw_reserved => "sw_reserved" });
    c.eq("_fpstate_64.__size", x64::XSTATE_LEGACY_SIZE);
    layout!(c, x64::UContext, "ucontext" {
        uc_flags => "uc_flags", uc_link => "uc_link", uc_stack => "uc_stack",
        uc_mcontext => "uc_mcontext", uc_sigmask => "uc_sigmask",
        uc_mcontext.rip => "uc_mcontext.rip", uc_mcontext.rsp => "uc_mcontext.rsp",
        uc_mcontext.fpstate => "uc_mcontext.fpstate" });
    layout!(c, x64::RtSigframe, "rt_sigframe" {
        pretcode => "pretcode", uc => "uc", info => "info" });
    c.finish();
}

